-- Knowledge and governed memory. PostgreSQL is the source of truth; indexes are derived.
BEGIN;
CREATE TABLE IF NOT EXISTS knowledge_documents(tenant_id text NOT NULL REFERENCES platform_tenants(tenant_id),document_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),title text NOT NULL,source_uri text NOT NULL,content_hash text NOT NULL,scope text NOT NULL CHECK(scope IN ('tenant','project','private')),project_id text,owner_user_id text,media_type text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(tenant_id,document_id,version),CHECK(scope<>'project' OR project_id IS NOT NULL),CHECK(scope<>'private' OR owner_user_id IS NOT NULL));
CREATE INDEX IF NOT EXISTS idx_knowledge_documents_scope ON knowledge_documents(tenant_id,scope,project_id,owner_user_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS knowledge_chunks(tenant_id text NOT NULL,document_id uuid NOT NULL,document_version integer NOT NULL,chunk_id uuid NOT NULL,ordinal integer NOT NULL,body text NOT NULL,content_hash text NOT NULL,start_offset integer NOT NULL,end_offset integer NOT NULL,page_number integer,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,search_vector tsvector GENERATED ALWAYS AS(to_tsvector('simple',body)) STORED,PRIMARY KEY(tenant_id,chunk_id),UNIQUE(tenant_id,document_id,document_version,ordinal),FOREIGN KEY(tenant_id,document_id,document_version) REFERENCES knowledge_documents(tenant_id,document_id,version) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_knowledge_chunks_fts ON knowledge_chunks USING gin(search_vector);
CREATE TABLE IF NOT EXISTS knowledge_embeddings(tenant_id text NOT NULL,chunk_id uuid NOT NULL,embedding_model text NOT NULL,embedding vector(1536) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,chunk_id,embedding_model),FOREIGN KEY(tenant_id,chunk_id) REFERENCES knowledge_chunks(tenant_id,chunk_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_knowledge_embeddings_cosine ON knowledge_embeddings USING hnsw(embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS knowledge_document_acl(tenant_id text NOT NULL,document_id uuid NOT NULL,principal_type text NOT NULL CHECK(principal_type IN ('user','role','project')),principal_id text NOT NULL,permission text NOT NULL CHECK(permission IN ('read','manage')),granted_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,document_id,principal_type,principal_id,permission));
CREATE TABLE IF NOT EXISTS platform_memories(tenant_id text NOT NULL REFERENCES platform_tenants(tenant_id),memory_id uuid NOT NULL,scope text NOT NULL CHECK(scope IN ('user','agent','project','tenant')),scope_id text NOT NULL,content text NOT NULL,source_ref text NOT NULL,confidence real NOT NULL CHECK(confidence BETWEEN 0 AND 1),status text NOT NULL CHECK(status IN ('candidate','active','expired','deleted')),version integer NOT NULL DEFAULT 1,created_by text NOT NULL,confirmed_by text,expires_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(tenant_id,memory_id));
CREATE INDEX IF NOT EXISTS idx_platform_memories_scope ON platform_memories(tenant_id,scope,scope_id,updated_at DESC) WHERE status='active' AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_platform_memories_expiry ON platform_memories(expires_at) WHERE status='active' AND expires_at IS NOT NULL;
COMMIT;
